//If(CountRows([@PowerBIIntegration].Data)=1,If(IsBlank(LookUp(Getdata,record_id=First([@PowerBIIntegration].Data).record_id)),"",LookUp(Getdata,record_id=First([@PowerBIIntegration].Data).record_id).scientific_reviewer_comment),"")
If(
    CountRows([@PowerBIIntegration].Data) = 1,
    With(
        { 
            _CurrentRecord: LookUp(Getdata, record_id = First([@PowerBIIntegration].Data).record_id) 
        },
        If(
            IsBlank(_CurrentRecord),
            "", 
            If(
                // Priority 1: Check if manual comment exists and is not empty
                !IsBlank(_CurrentRecord.scientific_reviewer_comment) && Len(_CurrentRecord.scientific_reviewer_comment) > 0,
                _CurrentRecord.scientific_reviewer_comment,
                
                // Priority 2: Fallback to AI comment if manual is missing
                !IsBlank(_CurrentRecord.scientific_reviewer_comment_by_ai) && Len(_CurrentRecord.scientific_reviewer_comment_by_ai) > 0,
                _CurrentRecord.scientific_reviewer_comment_by_ai,
                
                // Priority 3: Default to empty string
                ""
            )
        )
    ),
    ""
)

